#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# 用法：bash scripts/cws-service-account-wizard.sh
#   設定 release workflow 自動上傳 Chrome Web Store 用的 service account（#84）：
#   GCP 建 service account 與 JSON key → GitHub secret CWS_SERVICE_ACCOUNT_KEY → Dashboard 加入 service account，
#   最後用 Chrome Web Store API 實際查一次項目狀態，確認整條路通了。
#   不是秘密的值（GCP 專案 ID、service account email）存在 repo 外的 ~/.config/naruhodo/webstore.env，重跑時沿用。
#   規則與出處見 docs/research/chrome-web-store-listing.md 第 8 節。

# win_path：去掉拖曳檔案帶進來的引號；Git Bash 下把 C:\... 轉成 /c/...。
win_path() {
  local p="$1"
  p="${p%\"}"; p="${p#\"}"; p="${p%\'}"; p="${p#\'}"
  if command -v cygpath >/dev/null 2>&1; then cygpath -u "$p"; else printf '%s' "$p"; fi
}

# key_email FILE：service account JSON key 的 client_email；不是 service account key 就失敗。
key_email() {
  KEY_FILE="$1" node -e '
    const k = JSON.parse(require("fs").readFileSync(process.env.KEY_FILE, "utf8"));
    if (k.type !== "service_account" || !k.private_key || !k.client_email) process.exit(1);
    process.stdout.write(k.client_email);' 2>/dev/null
}

# fetch_status FILE PUBLISHER EXTENSION：用 key 自己簽 JWT 換 access token（跟 scripts/webstore-publish.ts 同一種做法），
# 呼叫只讀的 fetchStatus。印出 HTTP 狀態與回應開頭；不是 2xx 就失敗。
fetch_status() {
  KEY_FILE="$1" PUB="$2" EXT="$3" node -e '
    const { sign } = require("crypto");
    const k = JSON.parse(require("fs").readFileSync(process.env.KEY_FILE, "utf8"));
    const b64 = (s) => Buffer.from(s).toString("base64url");
    const now = Math.floor(Date.now() / 1000);
    const head = b64(JSON.stringify({ alg: "RS256", typ: "JWT" }));
    const claims = b64(JSON.stringify({ iss: k.client_email, scope: "https://www.googleapis.com/auth/chromewebstore", aud: k.token_uri, iat: now, exp: now + 600 }));
    const jwt = head + "." + claims + "." + b64(sign("RSA-SHA256", Buffer.from(head + "." + claims), k.private_key));
    (async () => {
      const t = await fetch(k.token_uri, { method: "POST", body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion: jwt }) });
      const token = (await t.json()).access_token;
      if (!token) { console.log("取得 access token 失敗：HTTP " + t.status); process.exit(1); }
      const url = "https://chromewebstore.googleapis.com/v2/publishers/" + process.env.PUB + "/items/" + process.env.EXT + ":fetchStatus";
      const r = await fetch(url, { headers: { authorization: "Bearer " + token } });
      console.log("HTTP " + r.status + " " + (await r.text()).slice(0, 400));
      process.exit(r.ok ? 0 : 1);
    })();'
}

run_wizard() {

TOTAL_STAGES=8

cd "$(git rev-parse --show-toplevel)"
for tool in node gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "需要 $tool，請先安裝"; exit 1; }
done
mkdir -p "$HOME/.config/naruhodo"
ENV_FILE="$HOME/.config/naruhodo/webstore.env"

banner "Chrome Web Store 自動上傳：service account（#84）"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "確認 gh 與 Dashboard 的 ID"
say "release workflow 要三個值才會上傳：CWS_PUBLISHER_ID、CWS_EXTENSION_ID（GitHub variable）"
say "與 CWS_SERVICE_ACCOUNT_KEY（GitHub secret）。這個 wizard 補上最後一個。"
if ! gh auth status >/dev/null 2>&1; then
  step "gh 還沒登入，接著執行 gh auth login。"
  gh auth login
fi
note "GitHub repo：$(gh repo view --json nameWithOwner -q .nameWithOwner)"
CWS_PUBLISHER_ID=$(gh variable get CWS_PUBLISHER_ID 2>/dev/null || true)
CWS_EXTENSION_ID=$(gh variable get CWS_EXTENSION_ID 2>/dev/null || true)
if [[ -z "$CWS_PUBLISHER_ID" ]]; then
  step "Dashboard → Settings 的 Publisher ID。"
  ask CWS_PUBLISHER_ID "貼上 Publisher ID："
  set_var CWS_PUBLISHER_ID "$CWS_PUBLISHER_ID"
fi
if [[ -z "$CWS_EXTENSION_ID" ]]; then
  step "Dashboard → Items 裡 Naruhodo 的 ID（32 個小寫字母）。"
  ask CWS_EXTENSION_ID "貼上 Extension ID："
  set_var CWS_EXTENSION_ID "$CWS_EXTENSION_ID"
fi
note "CWS_PUBLISHER_ID = $CWS_PUBLISHER_ID"
note "CWS_EXTENSION_ID = $CWS_EXTENSION_ID"
if gh secret list 2>/dev/null | grep -q '^CWS_SERVICE_ACCOUNT_KEY\b'; then
  warn "GitHub 已經有 CWS_SERVICE_ACCOUNT_KEY。"
  confirm "要重新設定嗎？（一個 publisher 只能連一個 service account）" || { note "沒有變更。"; exit 0; }
fi
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "選一個 GCP 專案"
say "service account 要放在某個 GCP 專案底下。用公司帳號（sadcoder.com）登入。"
open_url "https://console.cloud.google.com/projectselector2/home/dashboard"
step "選一個現有的專案，或按 New project 建一個（名稱例如 naruhodo）。"
step "專案 ID 在專案選單或 Dashboard 的 Project info 卡片上（不是專案名稱）。"
ask GCP_PROJECT_ID "貼上專案 ID："
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "啟用 Chrome Web Store API"
open_url "https://console.cloud.google.com/apis/library/chromewebstore.googleapis.com?project=$GCP_PROJECT_ID"
step "確認上方的專案是 $GCP_PROJECT_ID，按 Enable（已經顯示 Manage 就代表啟用過了）。"
pause "啟用後按 Enter"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "建立 service account"
say "這個帳號不需要任何 IAM 角色：上傳權限是在 Web Store Dashboard 那一端給的。"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=$GCP_PROJECT_ID"
step "Service account name 填 cws-publisher，按 Create and continue。"
step "授予專案權限、授予使用者存取這兩步都跳過，按 Done。"
step "在清單裡複製它的 email（像 cws-publisher@$GCP_PROJECT_ID.iam.gserviceaccount.com）。"
while :; do
  ask CWS_SERVICE_ACCOUNT_EMAIL "貼上 service account email："
  [[ "$CWS_SERVICE_ACCOUNT_EMAIL" == *@*.iam.gserviceaccount.com ]] && break
  warn "應該以 .iam.gserviceaccount.com 結尾，再複製一次"
done
write_env CWS_SERVICE_ACCOUNT_EMAIL "$CWS_SERVICE_ACCOUNT_EMAIL"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "建立 JSON key，存成 GitHub secret"
say "JSON key 等同 service account 的密碼：只放進 GitHub secret，不貼到任何對話或檔案裡。"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=$GCP_PROJECT_ID"
step "點 $CWS_SERVICE_ACCOUNT_EMAIL → Keys 分頁 → Add key → Create new key → JSON → Create。"
step "瀏覽器會下載一個 .json 檔。"
warn "出現 iam.disableServiceAccountKeyCreation 的錯誤，代表公司的 org policy 禁止建立 key："
note "  要對這個專案關掉該政策（IAM & Admin → Organization policies，需要 Organization Policy Administrator）。"
note "  也可以先按 Ctrl-C 停下，處理好再重跑，前面填過的值會沿用。"
while :; do
  ask KEY_FILE_INPUT "下載的 .json 路徑（可以從檔案總管拖進來）："
  KEY_FILE=$(win_path "$KEY_FILE_INPUT")
  if [[ ! -f "$KEY_FILE" ]]; then warn "找不到檔案：$KEY_FILE"; continue; fi
  if ! KEY_EMAIL=$(key_email "$KEY_FILE"); then warn "不是 service account 的 JSON key"; continue; fi
  [[ "$KEY_EMAIL" == "$CWS_SERVICE_ACCOUNT_EMAIL" ]] && break
  warn "這把 key 屬於 $KEY_EMAIL，不是 $CWS_SERVICE_ACCOUNT_EMAIL"
done
set_secret CWS_SERVICE_ACCOUNT_KEY "$(cat "$KEY_FILE")"
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "在 Web Store Dashboard 加入 service account"
say "Dashboard 要認得這個 service account，它才能上傳到你的 publisher。"
open_url "https://chrome.google.com/webstore/devconsole/$CWS_PUBLISHER_ID/settings"
step "如果開到別的 Google 帳號，右上角切到 publisher 的帳號（dev@sadcoder.com）。"
step "在 Settings 頁找到 service account 的區塊，加入這個 email："
note "    $CWS_SERVICE_ACCOUNT_EMAIL"
note "  一個 publisher 只能連一個 service account；已經有別的就先移除。"
pause "加好、存檔後按 Enter"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "用 API 實際查一次項目狀態"
say "用剛才的 key 換 access token，呼叫 fetchStatus（只讀，不會上傳或送審）。"
while :; do
  if RESULT=$(fetch_status "$KEY_FILE" "$CWS_PUBLISHER_ID" "$CWS_EXTENSION_ID"); then
    printf '  %s✓ API 回應正常%s\n' "$GREEN" "$RESET"
    note "$RESULT"
    break
  fi
  warn "$RESULT"
  note "403：Chrome Web Store API 沒啟用（第 3 步），或 Dashboard 還沒加入 service account（第 6 步，生效可能要幾分鐘）。"
  note "404：Publisher ID 或 Extension ID 不對。"
  confirm "修正後再試一次？" || { SKIPPED+=("API 驗證沒通過：修正後重跑這個 wizard"); break; }
done
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "刪除本機的 JSON key"
say "key 已經在 GitHub secret 裡；留在電腦上沒有用處，只多一個外洩的地方。"
say "要換 key 時：GCP 建一把新的、重跑這個 wizard，再到 GCP 刪掉舊的 key。"
note "$KEY_FILE"
if confirm "刪除這個檔案？"; then
  rm -f "$KEY_FILE"
  printf '  %s✓ 已刪除%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("刪除本機的 JSON key：$KEY_FILE")
fi
pause

finish
note "下次發 release 時，workflow 的 Web Store 上傳步驟就會執行（.github/workflows/release.yml）。"
}

run_wizard "$@"; exit
